def solve_n(n):
    a = [0] * n
    a[n-1] = 1
    for m in range(n-1, 0, -1):
        res = 0
        for i in range(m, n):
            res += a[i] * math.comb(i, m) * ((-1)**(i-m))
        if m == n:
            res += 1
        a[m-1] = res
    return sum(a[i] * ((-1)**i) for i in range(n)) == 0

possible_n = []
for n in range(1, 100):
    if solve_n(n):
        possible_n.append(n)
print(f"Possible n: {possible_n}")
