import numpy as np

def solve_n(n):
    if n == 1:
        return False
    matrix = []
    for k in range(1, n+1):
        row = []
        for i in range(n):
            row.append(k**(i+1) - (k-1)**i)
        row.append(k**n)
        matrix.append(row)

    try:
        a_coeffs = np.linalg.solve(np.array(matrix, dtype=float), np.array([r[-1] for r in matrix], dtype=float))
        if all(np.isclose(a_coeffs, np.round(a_coeffs))):
            return True
    except np.linalg.LinAlgError:
        return False
    return False

possible_n = []
for n in range(1, 31):
    if solve_n(n):
        possible_n.append(n)
print(f"Possible n: {possible_n}")

